-- KELANA: tempat budaya DI Yogyakarta (data nyata). Menggantikan SELURUH data contoh (is_sample = true).
-- Sumber: docs/data/tempat-diy.json (dikumpulkan 2026-11-25/26, disetujui user). Setiap fakta resmi membawa source_url dan checked_at;
-- checked_at null berarti sumbernya lama/tidak terbaca dan app menampilkan 'sedang dicek'.
-- cap_code/passport_order: nomor cap lama dipakai ulang untuk 7 tempat yang sama (YK-01,02,03,05,06,09,10), sisanya penomoran sementara.
-- cap_radius_m = 150 untuk semua tempat (keputusan user 2026-11-26; dapat disesuaikan per tempat nanti).
-- BYPASS PEMERIKSAAN (sementara, keputusan user 2026-11-26): jam dan tiket yang punya nilai dan source_url tetapi checked_at kosong
-- (sumber lama/tidak bertanggal, tetapi halamannya sudah dibaca saat pengumpulan) diberi checked_at = 2026-11-26 agar tampil di app.
-- Tanggal itu = tanggal halaman dibaca, BUKAN konfirmasi pengelola. Baris bypass diberi komentar [bypass]; tarik kembali dengan checked_at = null.
-- 2026-11-26: tiket hanya tiket masuk (parkir, paket, workshop, tambahan, tiket pertunjukan dikeluarkan). Sendratari Ramayana dan pagelaran wayang Sonobudoyo
-- menjadi event di tempat tuan rumahnya: lihat supabase/data/events_hosted.sql (jalankan setelah file ini).
begin;

-- 1) hapus data contoh (tabel anak ikut terhapus lewat cascade pada places)
delete from public.stamps where is_sample;
delete from public.postcards where is_sample;
delete from public.videos where is_sample;
delete from public.events where is_sample;
delete from public.opening_hours where is_sample;
delete from public.closures where is_sample;
delete from public.ticket_prices where is_sample;
delete from public.places where is_sample;
delete from auth.users where id in (select id from public.profiles where is_sample);
delete from public.profiles where is_sample;
-- Daftar wilayah dipakai app (Pilih wilayah, 'segera hadir') dan dirujuk places/profiles: dipertahankan, bukan data contoh lagi.
update public.regions set is_sample = false where is_sample;

-- 2) tempat nyata
-- Keraton Ngayogyakarta Hadiningrat
insert into public.places (region_id, slug, name, category, cap_code, passport_order, cap_radius_m, location, address, description, is_sample)
select r.id, 'keraton-yogyakarta', 'Keraton Ngayogyakarta Hadiningrat', 'lainnya'::public.place_category, 'YK-01', 1, 150, extensions.st_setsrid(extensions.st_makepoint(110.36406, -7.805689), 4326)::extensions.geography, 'Jl. Rotowijayan Blok No.1, Panembahan, Kecamatan Kraton, Kota Yogyakarta, Daerah Istimewa Yogyakarta', 'Keraton Ngayogyakarta Hadiningrat adalah kediaman resmi Sultan Yogyakarta, didirikan pada 1755 oleh Sri Sultan Hamengkubuwana I setelah pembagian Mataram lewat Perjanjian Giyanti. Sebagian kompleksnya dibuka untuk wisatawan dan dikelola oleh Kawedanan Radya Kartiyasa. Jam dan tarif kunjungan sebaiknya dicek ulang sebelum datang.', false
from public.regions r where r.code = 'DIY'
on conflict (slug) do update set name = excluded.name, category = excluded.category, cap_radius_m = excluded.cap_radius_m, location = excluded.location, address = excluded.address, description = excluded.description;
delete from public.opening_hours where place_id = (select id from public.places where slug = 'keraton-yogyakarta');
delete from public.ticket_prices where place_id = (select id from public.places where slug = 'keraton-yogyakarta');
