-- Taman Sari
insert into public.places (region_id, slug, name, category, cap_code, passport_order, cap_radius_m, location, address, description, is_sample)
select r.id, 'taman-sari', 'Taman Sari', 'lainnya'::public.place_category, 'YK-03', 3, 150, extensions.st_setsrid(extensions.st_makepoint(110.3591533, -7.8100322), 4326)::extensions.geography, 'Jalan Tamanan, Patehan, Kecamatan Kraton, Kota Yogyakarta, Daerah Istimewa Yogyakarta 55133', 'Taman Sari adalah kompleks taman dan pesanggrahan milik Keraton Yogyakarta yang dibangun bertahap sejak 1758 pada masa Sultan Hamengku Buwono I. Dahulu area seluas lebih dari 10 hektar ini dipakai sebagai kebun dan tempat pemandian kerabat kerajaan, lengkap dengan kolam, jembatan gantung, dan lorong bawah tanah. Bangunannya sempat rusak akibat gempa 1867 dan 2006, kini sebagian telah dipugar dan dibuka sebagai objek wisata.', false
from public.regions r where r.code = 'DIY'
on conflict (slug) do update set name = excluded.name, category = excluded.category, cap_radius_m = excluded.cap_radius_m, location = excluded.location, address = excluded.address, description = excluded.description;
