-- Museum Negeri Sonobudoyo
insert into public.places (region_id, slug, name, category, cap_code, passport_order, cap_radius_m, location, address, description, is_sample)
select r.id, 'museum-sonobudoyo', 'Museum Negeri Sonobudoyo', 'museum'::public.place_category, 'YK-02', 2, 150, extensions.st_setsrid(extensions.st_makepoint(110.3637812, -7.8021367), 4326)::extensions.geography, 'Jl. Pangurakan No. 6, Yogyakarta 55122 (Unit I, Alun-alun Utara)', 'Museum Negeri Sonobudoyo adalah museum daerah di Kota Yogyakarta yang dikelola oleh Pemerintah Daerah Istimewa Yogyakarta sebagai unit pelaksana teknis. Museum ini merawat, meneliti, dan memamerkan koleksi budaya serta ilmiah, termasuk benda-benda budaya Jawa. Pengunjung juga dapat menyaksikan pagelaran wayang dan gamelan.', false
from public.regions r where r.code = 'DIY'
on conflict (slug) do update set name = excluded.name, category = excluded.category, cap_radius_m = excluded.cap_radius_m, location = excluded.location, address = excluded.address, description = excluded.description;
