-- Candi Prambanan
insert into public.places (region_id, slug, name, category, cap_code, passport_order, cap_radius_m, location, address, description, is_sample)
select r.id, 'candi-prambanan', 'Candi Prambanan', 'candi'::public.place_category, 'YK-10', 10, 150, extensions.st_setsrid(extensions.st_makepoint(110.491465, -7.75202), 4326)::extensions.geography, 'Bokoharjo, Kecamatan Prambanan, Kabupaten Sleman, DI Yogyakarta (pintu administrasi berada di Tlogo, Klaten, Jawa Tengah)', 'Candi Prambanan adalah kompleks candi Hindu terbesar di Indonesia yang dibangun pada abad ke-9 dan didedikasikan untuk Trimurti: Brahma, Wisnu, dan Siwa. Candi Siwa di tengahnya menjulang sekitar 47 meter dan menjadi salah satu bangunan candi paling mengesankan di Asia Tenggara. Situs ini masuk Warisan Dunia UNESCO sejak 1991.', false
from public.regions r where r.code = 'DIY'
on conflict (slug) do update set name = excluded.name, category = excluded.category, cap_radius_m = excluded.cap_radius_m, location = excluded.location, address = excluded.address, description = excluded.description;
