-- Museum Benteng Vredeburg
insert into public.places (region_id, slug, name, category, cap_code, passport_order, cap_radius_m, location, address, description, is_sample)
select r.id, 'benteng-vredeburg', 'Museum Benteng Vredeburg', 'museum'::public.place_category, 'YK-05', 5, 150, extensions.st_setsrid(extensions.st_makepoint(110.3663, -7.8003), 4326)::extensions.geography, 'Jalan Margo Mulyo No. 6, Yogyakarta 55121', 'Museum Benteng Vredeburg menempati bekas benteng peninggalan kolonial yang tanahnya dimiliki Kesultanan Yogyakarta dan disewakan kepada pemerintah pusat. Sejak 1992 kompleks ini dikelola sebagai museum yang mengisahkan perjalanan perjuangan kemerdekaan Indonesia. Pengunjung dapat menjelajahi pameran sejarah bangsa di dalam area benteng.', false
from public.regions r where r.code = 'DIY'
