-- Situs Ratu Boko
insert into public.places (region_id, slug, name, category, cap_code, passport_order, cap_radius_m, location, address, description, is_sample)
select r.id, 'situs-ratu-boko', 'Situs Ratu Boko', 'lainnya'::public.place_category, 'YK-07', 7, 150, extensions.st_setsrid(extensions.st_makepoint(110.4894642, -7.770512), 4326)::extensions.geography, 'Bokoharjo dan Sambirejo, Kecamatan Prambanan, Kabupaten Sleman, Daerah Istimewa Yogyakarta', 'Situs Ratu Boko berupa kompleks keraton di atas bukit sekitar 3 km selatan Candi Prambanan. Berbeda dengan monumen Jawa kuno pada umumnya, situs ini merupakan tempat tinggal kerajaan yang bersifat sekuler, dilengkapi gerbang, pendopo, kolam pemandian, dan tembok benteng dengan parit kering. Situs ini diperkirakan digunakan sejak abad ke-8.', false
from public.regions r where r.code = 'DIY'
on conflict (slug) do update set name = excluded.name, category = excluded.category, cap_radius_m = excluded.cap_radius_m, location = excluded.location, address = excluded.address, description = excluded.description;
