-- Masjid Gedhe Kauman
insert into public.places (region_id, slug, name, category, cap_code, passport_order, cap_radius_m, location, address, description, is_sample)
select r.id, 'masjid-gedhe-kauman', 'Masjid Gedhe Kauman', 'lainnya'::public.place_category, 'YK-11', 11, 150, extensions.st_setsrid(extensions.st_makepoint(110.3623919, -7.8038203), 4326)::extensions.geography, 'Gang Monumen Syuhada, Prawirodirjan, Gondomanan, Kota Yogyakarta, Daerah Istimewa Yogyakarta 55132', 'Masjid Gedhe Kauman adalah masjid raya Kasultanan Yogyakarta yang berdiri di sisi barat alun-alun utara, berdekatan dengan kompleks Keraton. Bangunannya beratap tumpang tiga dengan gaya Jawa dan memiliki mihrab, maksura, serta mimbar kayu jati yang khas. Masjid ini juga menjadi pusat kegiatan Ramadan dan bagian dari rangkaian tradisi Grebeg.', false
from public.regions r where r.code = 'DIY'
on conflict (slug) do update set name = excluded.name, category = excluded.category, cap_radius_m = excluded.cap_radius_m, location = excluded.location, address = excluded.address, description = excluded.description;
