-- Taman Budaya Yogyakarta (TBY)
insert into public.places (region_id, slug, name, category, cap_code, passport_order, cap_radius_m, location, address, description, is_sample)
select r.id, 'taman-budaya-yogyakarta', 'Taman Budaya Yogyakarta (TBY)', 'tari'::public.place_category, 'YK-14', 14, 150, extensions.st_setsrid(extensions.st_makepoint(110.367656, -7.8001356), 4326)::extensions.geography, 'Jl. Sriwedani No.1, Ngupasan, Kec. Gondomanan, Kota Yogyakarta, DI Yogyakarta 55122', 'Taman Budaya Yogyakarta adalah pusat kegiatan seni dan budaya di Jalan Sriwedani, Kota Yogyakarta, dan menjadi tempat pameran, pertunjukan, serta festival. Gedungnya juga dipakai untuk pertemuan seni dan temu karya budaya tingkat nasional.', false
from public.regions r where r.code = 'DIY'
on conflict (slug) do update set name = excluded.name, category = excluded.category, cap_radius_m = excluded.cap_radius_m, location = excluded.location, address = excluded.address, description = excluded.description;
delete from public.opening_hours where place_id = (select id from public.places where slug = 'taman-budaya-yogyakarta');
delete from public.ticket_prices where place_id = (select id from public.places where slug = 'taman-budaya-yogyakarta');

